<?php $title='Staff Detail';require __DIR__.'/includes/header.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM users WHERE id=? AND role="staff"');$s->execute([$id]);$staff=$s->fetch();if(!$staff)exit('Staff member not found.');$s=db()->prepare('SELECT a.id,a.ref_number,a.created_at,p.amount FROM archives a LEFT JOIN payments p ON p.archive_id=a.id WHERE a.created_by=? ORDER BY a.created_at DESC');$s->execute([$id]);$archives=$s->fetchAll();$s=db()->prepare('SELECT * FROM activity_logs WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$s->execute([$id]);$logs=$s->fetchAll();?><div class="page-head"><div><h1><?=e($staff['full_name'])?></h1><p class="muted">@<?=e($staff['username'])?> · <?=e(ucfirst($staff['status']))?></p></div><a class="btn light" href="staff_performance.php">Back to performance</a></div><div class="grid grid-2"><div class="card"><h2>Archives added</h2><strong class="metric"><?=count($archives)?></strong></div><div class="card"><h2>Recent activity</h2><strong class="metric"><?=count($logs)?></strong></div></div><div class="card form-section"><h2>Archives</h2><div class="table-wrap"><table class="table"><thead><tr><th>Reference</th><th>Date</th><th>Payment</th><th></th></tr></thead><tbody><?php foreach($archives as $a):?><tr><td><?=e($a['ref_number'])?></td><td><?=e(date('M j, Y',strtotime($a['created_at'])))?></td><td><?= $a['amount']!==null?CURRENCY.number_format((float)$a['amount'],2):'<span class="badge pending">Pending</span>'?></td><td><a class="btn light" href="archive_view.php?id=<?=$a['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><h2>Activity timeline</h2><?php foreach($logs as $l):?><p><span class="badge paid"><?=e($l['action'])?></span> <?=e($l['details']??'')?> <small class="muted">· <?=e(date('M j, g:i A',strtotime($l['created_at'])))?></small></p><?php endforeach;?></div><?php require __DIR__.'/includes/footer.php';
